from .config import Fragment, Journal, Remote, RemoteScheme, Scheme, Site, current
STAMP = '*Generated by `luria index` from the dataclasses in `luria/config.py` — built, not edited. A key that exists in the schema is a row here whether or not anyone remembered to describe it.*\n'
MARKER = '<!-- GENERATED by `luria index` — edit `luria/config.py`'
HEADER = '# Configuration\n\n<!-- GENERATED by `luria index` — edit `luria/config.py`, not this file. -->\n\n{stamp}\nEverything Luria does is driven by one file at the project root,\n`luria.toml`. **Every key has a default**, so a project with the conventional\nlayout needs only `issue_url` — and Luria runs without the file at all, on\ndefaults alone, which is what lets `luria init` bootstrap into an empty\nrepository.\n\n## The shape of the file\n\nThe tables below are the whole schema. Four of them — `schemes`, `fragments`,\n`journals` and `remotes` — are *families*: you name the entries, and the name\nyou choose becomes part of the vocabulary. `[luria.schemes.RFC]` is how a\nproject gets RFCs; `[luria.journals.incidents]` is how it gets a second\njournal. No code path spells `ADR`.\n\nThat is worth stating plainly, because this package ships one instantiation of\nits own machinery — decisions, principles, a changelog and a devlog — and it\nis easy to read those four as Luria\'s parts. They are its defaults. A record\nmade of RFCs, specs and a meeting log is the same engine with different\ntables.\n\nTwo merge rules follow from that split (ADR-047). A *settings* table —\n`paths`, `code`, `lint`, `site` — merges per key: setting `docs` does not\nclear `reports`. A *family* table is **replaced whole the moment you declare\nit**: a project that writes `[luria.schemes.RFC]` and nothing else has\nexactly one scheme, and the shipped `ADR` is simply absent. Declare a family\nand it is yours entirely; leave it undeclared and the default stands. This is\nalso what makes omission meaningful inside a declared family — an `output`\nyou leave out is genuinely unset, because there is no default entry left for\nit to inherit from.\n\n| table | what it configures | families |\n|---|---|---|\n| `[luria]` | issue links, staleness horizon | — |\n| `[luria.paths]` | where the read and write surfaces live | — |\n| `[luria.schemes.X]` | a referable document family: `ADR`, `RFC`, `SPEC` | yes, keyed by prefix |\n| `[luria.fragments."dir"]` | many small files assembled into one document | yes, keyed by directory |\n| `[luria.journals.X]` | dated entries that persist, rendered into books | yes, keyed by name |\n| `[luria.remotes.X]` | another project\'s codes, cited from this one | yes, keyed by prefix |\n| `[luria.code]` | which source files are scanned for stale references | — |\n| `[luria.lint]` | which warning classes fail the build | — |\n| `[luria.site]` | publishing the record as a browsable site | — |\n'
FOOTER = "\n## Environment variables\n\nTwo, both escape hatches rather than configuration — they change how a run\nbehaves, never what the record *is*, which is why they are not in the file.\n\n| variable | effect |\n|---|---|\n| `LURIA_ROOT` | the project root, overriding the search for `luria.toml` / `.git`. What lets the test suite run against fixture trees, and what a CI job uses when it checks out a project somewhere other than the working directory. |\n| `LURIA_JOBS` | caps the thread pool that renders views, scans files and probes remote URLs. `LURIA_JOBS=1` is the serial escape hatch — the one to reach for when a failure needs a deterministic ordering to reproduce. |\n\n## Running one module without the package\n\nEvery command is a plain function, and the modules stay runnable standalone:\n\n    python -m luria.ref_status --all\n\nThat is for a project that vendors a single file rather than installing\nLuria. The CLI is the supported surface; this is the door left unlocked.\n\n## What is not configurable\n\nSaid plainly, because a reference that only lists dials reads as though\neverything is one:\n\n- **The lint checks themselves.** They are functions, not a registry — a\n  project cannot add a check or switch one off. What it *can* do is promote\n  warning classes to failures with `[luria.lint] fail_on`, and acknowledge\n  individual findings with the comment directives. A check earns its place by\n  being always wrong and mechanically fixable; anything else is a report.\n- **The frontmatter vocabulary.** `status:`, `title:`, `tags:`, `date:`,\n  `version:`, `history:` are fixed field names. Which *statuses* count as in\n  force is per-scheme (`active`), but the field they live in is not.\n- **Renaming a scheme in place.** Adding `[luria.schemes.RFC]` costs one\n  table; renaming an existing scheme, or moving its documents, is currently a\n  manual pass — there is no migration command. The decision that would give\n  it one is still Proposed.\n\nTwo earlier entries in this list are gone because they stopped being true\n(ADR-047): the shipped `ADR` scheme *can* be removed — declare the `schemes`\nfamily without it — and a declared scheme's `output` *is* unset by omission,\nbecause a declared family no longer inherits from the defaults. Both are\ndemonstrated and pinned by `examples/` in the Luria repository, which CI\nruns.\n"
SECTIONS: list[tuple[str, type, str]] = [('Schemes — `[luria.schemes.X]`', Scheme, 'One entry per referable document family. The key is the prefix codes carry, so `[luria.schemes.RFC]` makes `RFC-7` a first-class reference: `luria link --fix` writes its link, `luria lint` demands one, and `luria new rfc` scaffolds the next free number — none of which needs anything beyond the table.'), ('Fragment directories — `[luria.fragments."dir"]`', Fragment, 'One entry per directory whose files are assembled into a single document and then consumed. The changelog is the shipped instance; the mechanism is not changelog-shaped.'), ('Journals — `[luria.journals.X]`', Journal, 'One entry per stream of dated entries that persist. This is a family like any other — a project can run a devlog, a meeting log and an incident log side by side, each with its own granularity and output.'), ('Remotes — `[luria.remotes.X]`', Remote, 'One entry per foreign project whose codes this record cites. The `uid` key is the general case: with a regex and a URL template, a remote need not hold a Luria-shaped record — or any record — at all, which is how arXiv identifiers, ticket keys and CVE numbers become linted references.'), ('Per-scheme remote construction — `[luria.remotes.X.schemes.Y]`', RemoteScheme, 'Optional, and only for a remote whose code families do not all construct the same way — a file per code in one, sections of a single page in another.'), ('The site — `[luria.site]`', Site, 'Publishing the record as a browsable vault. Every key derives from `issue_url` for a GitHub project, so the conventional case needs no table at all.')]
PLAIN: list[tuple[str, str, str, list[tuple[str, str]]]] = [('Top level — `[luria]`', '', '', [('issue_url', 'A template for issue links, with `{n}` for the number. Writing it also tells Luria which GitHub repository this is, which is where every `[luria.site]` default comes from. Unset, issue numbers stay bare rather than linking somewhere wrong.'), ('stale_days', 'How long a document may sit undecided before the pending-decisions report calls it out.')]), ('Paths — `[luria.paths]`', 'paths', 'The read/write boundary: `docs/` is where a reader browses, `record/` is where a contributor files.', [('docs', 'The read surface — prose plus every generated view.'), ('decisions', "The default scheme's source directory. Kept as its own key for projects that predate `[luria.schemes.X]`."), ('design_principles', 'Where the principles document renders.'), ('reports', 'Where the status reports land. Committed views rather than build artifacts, so a README badge has a real page to point at.')]), ('Code scanning — `[luria.code]`', 'code', 'Which files outside the record are checked for references to retired documents. A decision number in a code comment is the strongest form of the claim being checked — it is the stated reason the code is shaped that way.', [('globs', 'Source files to scan, as glob patterns.'), ('historical', 'Files that are true about the day they were written and never updated — scanning them produces permanent, unactionable noise. Journals are covered automatically.')]), ('Enforcement — `[luria.lint]`', 'lint', 'The dial between reported and enforced. Status findings are warnings by default; a class named here fails `luria lint` instead. Acknowledgement directives keep working under enforcement, because only unacknowledged rows ever reach a class.', [('fail_on', 'Warning classes promoted to failures.'), ('narrow_terms', "This project's own concrete nouns. A title in a scheme marked `titles_generalize` that names one is reported as `narrow-titles`. Luria ships none — the words are yours, and empty means the class never fires.")])]
_INDENTED = re.compile('(?m)^(?:    .*(?:\\n|$))+')

def fence(text: str, lang: str='toml') -> str:

    def swap(m: re.Match) -> str:
        body = '\n'.join((line[4:] for line in m.group(0).rstrip('\n').split('\n')))
        return f'```{lang}\n{body}\n```\n'
    return _INDENTED.sub(swap, text)
FROM_TABLE_NAME: dict[type, set[str]] = {Scheme: {'prefix'}, Journal: {'name'}, Remote: {'prefix'}, RemoteScheme: {'prefix'}}
DERIVED: dict[type, set[str]] = {Site: {'title', 'base_url', 'source_url'}}

def rows(cls: type) -> list[tuple[str, str, str]]:
    out = []
    for f in dataclasses.fields(cls):
        if f.name.startswith('_'):
            continue
        if f.default is not dataclasses.MISSING:
            shown = f.default
        elif f.default_factory is not dataclasses.MISSING:
            shown = f.default_factory()
        else:
            shown = dataclasses.MISSING
        if f.name in FROM_TABLE_NAME.get(cls, ()):
            label = "*the table's own name*"
        elif f.name in DERIVED.get(cls, ()):
            label = '*derived from `issue_url`*'
        else:
            label = _render_default(shown)
        out.append((f.name, str(f.type), label))
    return out

def _render_default(value) -> str:
    if value is dataclasses.MISSING:
        return '*required*'
    if value in ((), [], {}, '', None):
        return '*unset*'
    return f'`{value!r}`' if not isinstance(value, str) else f'`"{value}"`'

def table(cls: type) -> str:
    lines = ['| key | type | default |', '|---|---|---|']
    for name, type_, default in rows(cls):
        lines.append(f'| `{name}` | `{escape_cell(type_)}` | {default} |')
    return '\n'.join(lines) + '\n'

def plain_table(keys: list[tuple[str, str]], defaults: dict) -> str:
    lines = ['| key | default | what it does |', '|---|---|---|']
    for name, prose in keys:
        lines.append(f"| `{name}` | {_render_default(defaults.get(name, ''))} | {prose} |")
    return '\n'.join(lines) + '\n'

def render() -> str:
    parts = [HEADER.format(stamp=STAMP)]
    for title, subtree, blurb, keys in PLAIN:
        defaults = config_mod.DEFAULTS.get(subtree, {}) if subtree else config_mod.DEFAULTS
        parts.append(f'\n## {title}\n')
        if blurb:
            parts.append(f'\n{blurb}\n')
        parts.append('\n' + plain_table(keys, defaults))
    for title, cls, blurb in SECTIONS:
        parts.append(f'\n## {title}\n\n{blurb}\n\n')
        parts.append(fence(inspect.getdoc(cls) or '').rstrip('\n') + '\n\n')
        parts.append(table(cls))
    parts.append(FOOTER)
    return ''.join(parts)

def outputs(out_dir: Path | None=None) -> dict[Path, str]:
    cfg = current()
    path = cfg.config_doc if out_dir is None else out_dir / 'configuration.md'
    return {path: render()}

def retire() -> list[Path]:
    cfg = current()
    path = cfg.config_doc
    if cfg.owns_schema or not path.exists():
        return []
    if MARKER not in path.read_text():
        return []
    path.unlink()
    return [path]

def write(out_dir: Path | None=None) -> list[Path]:
    rendered = outputs(out_dir)
    for path, text in rendered.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
    return sorted(rendered)
if __name__ == '__main__':
    import fire
    fire.Fire(write)
